OUT=Path('benchmarks/obs-cef/2026-10-09-obs-long-control');REF=Path('benchmarks/obs-cef/2026-10-09-optimization/soak')
def read(path):return json.loads(path.read_text())
result=read(OUT/'result.json');validation=read(OUT/'media-validation.json');driver=read(OUT/'driver.json');samples=[json.loads(x) for x in (OUT/'status-samples.jsonl').read_text().splitlines()];processes=[json.loads(x) for x in (OUT/'processes.jsonl').read_text().splitlines()]
first=samples[0]['stats'];last=result['obsAfter'];renderSkipped=last['renderSkippedFrames']-result['obsBefore']['renderSkippedFrames'];renderTotal=last['renderTotalFrames']-result['obsBefore']['renderTotalFrames'];outputSkipped=last['outputSkippedFrames']-result['obsBefore']['outputSkippedFrames'];outputTotal=last['outputTotalFrames']-result['obsBefore']['outputTotalFrames']
telemetry={'statusSamples':len(samples),'processSamples':len(processes),'renderSkippedFrames':renderSkipped,'renderTotalFrames':renderTotal,'renderSkippedFraction':renderSkipped/renderTotal if renderTotal else None,'outputSkippedFrames':outputSkipped,'outputTotalFrames':outputTotal,'finalStream':result['finalStreamStatus'],'finalRecord':result['finalRecordStatus'],'maxControllerLoopDelayMs':result['eventLoopDelay']['maxMs']}
origin=processes[0]['monotonic'];gaps=[{'fromSeconds':a['monotonic']-origin,'toSeconds':b['monotonic']-origin,'gapSeconds':b['monotonic']-a['monotonic']} for a,b in zip(processes,processes[1:]) if b['monotonic']-a['monotonic']>2];telemetry['independentSamplerGapsOver2Seconds']=gaps
(OUT/'telemetry-summary.json').write_text(json.dumps(telemetry,indent=2))
fig,axes=plt.subplots(1,2,figsize=(10,4))
for ax,kind,title in [(axes[0],'audio','Longest silent interval'),(axes[1],'video','Longest frozen marker')]:
 labels=[];values=[];colors=[]
 for backend,color in [('suitecut','#d75c53'),('obs','#567bd4')]:
  for name in ['recording','receiver']:
   row=validation[backend][name];labels.append(backend+'\n'+name);values.append(row['audio']['longestSilentInterval']['durationSeconds'] if kind=='audio' else row['video']['longestContentHold']['durationSeconds']);colors.append(color)
 ax.bar(labels,values,color=colors);ax.set_title(title);ax.set_ylabel('Seconds');ax.axhline(5,color='black',ls='--',lw=1,label='5 s continuity failure limit');ax.legend(fontsize=8)
 for i,value in enumerate(values):ax.text(i,value,f'{value:.2f}',ha='center',va='bottom')
